fn caesar_shift(s: String, k: Int) -> String {
  let alphabet = split("a b c d e f g h i j k l m n o p q r s t u v w x y z", " ")
  let offset = (k % 26 + 26) % 26
  let tail = join(drop(alphabet, offset), "")
  let head = join(take(alphabet, offset), "")
  let shifted = split(tail + head, "")
  let substitutions = map_from(zip(alphabet, shifted))
  let characters = split(s, "")
  let result_chars = map(characters, |c| unwrap_or(map_get(substitutions, c), c))
  return join(result_chars, "")
}

