fn parse_duration(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  let chars = filter(split(s, ""), |ch| ch != "")
  var last_rank = 0
  var has_digits = false
  for ch in chars {
    if digit_value(ch) >= 0 {
      has_digits = true
    } else {
      let unit = duration_unit(ch)
      if unit.0 == 0 {
        return Err("unknown unit: " + ch)
      }
      if !has_digits {
        return Err("missing number before " + ch)
      }
      if unit.0 <= last_rank {
        return Err("unit out of order: " + ch)
      }
      last_rank = unit.0
      has_digits = false
    }
  }
  if has_digits {
    return Err("missing unit")
  }
  var total = 0
  var number = 0
  for ch in chars {
    let digit = digit_value(ch)
    if digit >= 0 {
      number = number * 10 + digit
    } else {
      let unit = duration_unit(ch)
      total = total + number * unit.1
      number = 0
    }
  }
  return Ok(total)
}

