def parse_duration(s: str) -> Ok[int] | Err:
    if not s:
        return {"ok": False, "error": "empty"}

    units: dict[str, tuple[int, int]] = {
        "h": (0, 3600),
        "m": (1, 60),
        "s": (2, 1),
    }
    total = 0
    last_rank = -1
    number: int | None = None

    for char in s:
        if char.isdecimal():
            number = (0 if number is None else number) * 10 + int(char)
            continue

        unit = units.get(char)
        if unit is None:
            return {"ok": False, "error": f"unknown unit: {char}"}
        if number is None:
            return {"ok": False, "error": f"missing number before {char}"}

        rank, multiplier = unit
        if rank <= last_rank:
            return {"ok": False, "error": f"unit out of order: {char}"}

        total += number * multiplier
        last_rank = rank
        number = None

    if number is not None:
        return {"ok": False, "error": "missing unit"}
    return {"ok": True, "value": total}

