type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

type Snapshot {
  chars: List[String],
  cursor: Int,
}

type Editor {
  current: Snapshot,
  history: List[Snapshot],
}

fn replace_range(editor: Editor, start: Int, end: Int, inserted: List[String]) -> Editor {
  let old = editor.current
  var chars = take(old.chars, start)
  for ch in inserted {
    chars = append(chars, ch)
  }
  for ch in drop(old.chars, end) {
    chars = append(chars, ch)
  }
  let current = Snapshot { chars: chars, cursor: start + len(inserted) }
  return Editor { current: current, history: append(editor.history, old) }
}

fn move_cursor(editor: Editor, cursor: Int) -> Editor {
  let current = Snapshot { chars: editor.current.chars, cursor: cursor }
  return Editor { current: current, history: editor.history }
}

fn undo_edit(editor: Editor) -> Editor {
  let history = editor.history
  let last_index = len(history) - 1
  return match last(history) {
    None => editor,
    Some(saved) => Editor { current: saved, history: take(history, last_index) },
  }
}

fn apply_edit(editor: Editor, op: EditOp) -> Editor {
  let cursor = editor.current.cursor
  let remaining = len(editor.current.chars) - cursor
  return match op {
    Insert(text) => replace_range(editor, cursor, cursor, split(text, "")),
    Delete(n) => replace_range(editor, cursor - min(n, cursor), cursor, []),
    Left(n) => move_cursor(editor, cursor - min(n, cursor)),
    Right(n) => move_cursor(editor, cursor + min(n, remaining)),
    Undo => undo_edit(editor),
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  let initial = Snapshot { chars: [], cursor: 0 }
  var editor = Editor { current: initial, history: [] }
  for op in ops {
    editor = apply_edit(editor, op)
  }
  return join(editor.current.chars, "")
}

